#!/bin/bash
# A script that collects all exported classes, functions and constants from the TS source and puts them in a global export file index.ts for npm packaging. Do NOT edit this file, or its output file.

{
    echo "// AUTO-GENERATED FILE — DO NOT EDIT MANUALLY."
    echo "// Generated automatically from the TypeScript source files."
    echo

    find src -name '*.ts' \
        ! -name 'index.ts' \
        ! -name '*.d.ts' \
        ! -path '*/_tests/*' \
        -exec grep -lE '^[[:space:]]*export[[:space:]{]' {} + \
        | sort \
        | sed -e 's|^src/|./|' \
              -e 's|\.ts$|.js|' \
              -e "s|^|export * from '|" \
              -e "s|$|'|"
} > src/index.ts
